/* ===== PS01-CODE 结构观感（v3.42.0，随深浅主题 token 化）===== */
/* 活动栏：左竖工具栏染 panel 色、方形、选中/hover 中性灰 */
QToolBar#sideTB {
  background: {bg_soft};
  border-right: 1px solid {tab_border};
}
QToolBar#sideTB QToolButton {
  border-radius: 3px;
}
/* 菜单：左内缩勾选位 + 方角 + 窄行距 */
QMenu {
  border-radius: 3px;
  padding: 3px;
}
QMenu::item {
  padding: 4px 24px 4px 22px;
  border-radius: 3px;
}
QMenu::separator { margin: 3px 6px; }
/* 页签：方角 + 面包屑感 */
QMainWindow #tabstrip QTabBar::tab:!selected {
  border-radius: 3px 3px 0 0;
}
/* 状态栏：VS Code 蓝底白字 */
QStatusBar {
  background: {accent};
  border-top: none;
  min-height: 24px;
}
QStatusBar QLabel {
  color: {status_fg};
  border-right: 1px solid {status_sep};
}
QStatusBar QToolButton {
  color: {status_fg};
}
QStatusBar QToolButton:hover {
  background: rgba(255,255,255,.12);
}
